class Solution {
public:
    bool isSubstringPresent(string s) {
        string r(s.rbegin(), s.rend());
        unordered_set<string> subs;
        for (int i = 0; i + 1 < (int)r.size(); i++) subs.insert(r.substr(i, 2));
        for (int i = 0; i + 1 < (int)s.size(); i++)
            if (subs.count(s.substr(i, 2))) return true;
        return false;
    }
};

