var isSubstringPresent = function(s) {
    const rev = [...s].reverse().join('');
    const subs = new Set();
    for (let i = 0; i + 1 < rev.length; i++) subs.add(rev.slice(i, i + 2));
    for (let i = 0; i + 1 < s.length; i++)
        if (subs.has(s.slice(i, i + 2))) return true;
    return false;
};

