class Solution {
public:
    bool isSubstringPresent(string s) {
        int n = s.size();
        for (int i = 0; i + 1 < n; i++) if (s[i] == s[i + 1]) return true;
        for (int i = 0; i + 2 < n; i++) if (s[i] == s[i + 2]) return true;
        return false;
    }
};

