class Solution {
    public boolean isSubstringPresent(String s) {
        int n = s.length();
        for (int i = 0; i + 1 < n; i++) if (s.charAt(i) == s.charAt(i + 1)) return true;
        for (int i = 0; i + 2 < n; i++) if (s.charAt(i) == s.charAt(i + 2)) return true;
        return false;
    }
}

